package ar.com.liftmanager.service;
import ar.com.liftmanager.dto.ApiDtos.*;import ar.com.liftmanager.model.*;import ar.com.liftmanager.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class VisitService {
 private final VisitRepository visits;private final ElevatorService elevatorService;private final UserRepository users;private final ContractRepository contracts;private final CurrentUserService current;private final ElevatorRepository elevatorRepo;
 private static final List<VisitStatus> BLOCKING=List.of(VisitStatus.SCHEDULED,VisitStatus.IN_PROGRESS);
 public VisitService(VisitRepository v,ElevatorService e,UserRepository u,ContractRepository c,CurrentUserService cu,ElevatorRepository er){visits=v;elevatorService=e;users=u;contracts=c;current=cu;elevatorRepo=er;}
 public List<VisitView> list(){AppUser me=current.get();List<MaintenanceVisit> all=me.getRole()==Role.TECHNICIAN?visits.findByTechnicianId(me.getId()):me.getRole()==Role.BUILDING_MANAGER?(me.getBuilding()==null?List.of():visits.findByElevatorBuildingId(me.getBuilding().getId())):visits.findAll();return all.stream().sorted(Comparator.comparing(MaintenanceVisit::getScheduledStart)).map(this::view).toList();}
 public VisitView create(VisitRequest r){current.requireAdmin();if(!SchedulingRules.validInterval(r.scheduledStart(),r.scheduledEnd()))throw BusinessException.badRequest("La visita debe tener una hora de fin posterior al inicio");if(r.scheduledStart().isBefore(LocalDateTime.now(ZoneId.of("America/Argentina/Buenos_Aires"))))throw BusinessException.badRequest("No se pueden programar visitas en el pasado");Elevator e=elevatorService.get(r.elevatorId());AppUser tech=users.findById(r.technicianId()).orElseThrow(()->BusinessException.notFound("Técnico no encontrado"));if(tech.getRole()!=Role.TECHNICIAN||!tech.isActive())throw BusinessException.badRequest("El usuario asignado debe ser un técnico activo");MaintenanceContract c=contracts.findByElevatorIdOrderByEndDateDesc(e.getId()).stream().filter(MaintenanceContract::isActive).filter(x->!r.scheduledStart().toLocalDate().isBefore(x.getStartDate())&&!r.scheduledStart().toLocalDate().isAfter(x.getEndDate())).findFirst().orElseThrow(()->BusinessException.badRequest("El ascensor no tiene contrato vigente para la fecha de la visita"));LocalDate date=r.scheduledStart().toLocalDate();if(!SchedulingRules.dateCovered(date,c.getStartDate(),c.getEndDate()))throw BusinessException.badRequest("La visita queda fuera de la vigencia del contrato");if(e.getStatus()==ElevatorStatus.OUT_OF_SERVICE)throw BusinessException.badRequest("No se puede programar mantenimiento normal: el ascensor está fuera de servicio");if(visits.existsByTechnicianIdAndStatusInAndScheduledStartLessThanAndScheduledEndGreaterThan(tech.getId(),BLOCKING,r.scheduledEnd(),r.scheduledStart()))throw BusinessException.conflict("El técnico ya tiene una visita en ese horario");if(visits.existsByElevatorIdAndStatusInAndScheduledStartLessThanAndScheduledEndGreaterThan(e.getId(),BLOCKING,r.scheduledEnd(),r.scheduledStart()))throw BusinessException.conflict("El ascensor ya tiene una visita en ese horario");MaintenanceVisit v=new MaintenanceVisit();v.setElevator(e);v.setTechnician(tech);v.setScheduledStart(r.scheduledStart());v.setScheduledEnd(r.scheduledEnd());v.setNotes(r.notes());return view(visits.save(v));}
 public VisitView start(Long id){MaintenanceVisit v=authorizedVisit(id);if(v.getStatus()!=VisitStatus.SCHEDULED)throw BusinessException.conflict("Solo se pueden iniciar visitas programadas");v.setStatus(VisitStatus.IN_PROGRESS);v.getElevator().setStatus(ElevatorStatus.UNDER_MAINTENANCE);elevatorRepo.save(v.getElevator());return view(visits.save(v));}
 @Transactional public VisitView complete(Long id,CompleteVisitRequest r){MaintenanceVisit v=authorizedVisit(id);if(v.getStatus()!=VisitStatus.IN_PROGRESS)throw BusinessException.conflict("La visita debe estar en proceso para poder cerrarse");v.setWorkPerformed(r.workPerformed().trim());v.setNotes(r.notes());v.setStatus(VisitStatus.COMPLETED);if(v.getElevator().getStatus()==ElevatorStatus.UNDER_MAINTENANCE)v.getElevator().setStatus(ElevatorStatus.OPERATIONAL);elevatorRepo.save(v.getElevator());return view(visits.save(v));}
 private MaintenanceVisit authorizedVisit(Long id){MaintenanceVisit v=visits.findById(id).orElseThrow(()->BusinessException.notFound("Visita no encontrada"));AppUser me=current.get();if(me.getRole()!=Role.ADMIN&&!v.getTechnician().getId().equals(me.getId()))throw BusinessException.forbidden("La visita no está asignada a tu usuario");return v;}
 private VisitView view(MaintenanceVisit v){return new VisitView(v.getId(),v.getElevator().getId(),v.getElevator().getCode(),v.getElevator().getBuilding().getName(),v.getTechnician().getId(),v.getTechnician().getName(),v.getScheduledStart(),v.getScheduledEnd(),v.getStatus(),v.getWorkPerformed(),v.getNotes());}
}
